body:
But it might make sense to handle Numpad the same way as Ctrl/Alt/Meta for the text input.

<details>
<summary>Patch - click to expand</summary>

```diff
diff --git a/scene/gui/code_edit.cpp b/scene/gui/code_edit.cpp
index 776afd599f..7ecc6a9f00 100644
--- a/scene/gui/code_edit.cpp
+++ b/scene/gui/code_edit.cpp
@@ -705,9 +705,9 @@ void CodeEdit::gui_input(const Ref<InputEvent> &p_gui_input) {
 	}

 	// Allow unicode handling if:
 	// No modifiers are pressed (except Shift and CapsLock)
-	bool allow_unicode_handling = !(k->is_ctrl_pressed() || k->is_alt_pressed() || k->is_meta_pressed());
+	bool allow_unicode_handling = !(k->is_ctrl_pressed() || k->is_alt_pressed() || k->is_meta_pressed() || (k->get_keycode() >= Key::KP_MULTIPLY && k->get_keycode() <= Key::KP_9));

 	/* AUTO-COMPLETE */
 	if (code_completion_enabled && k->is_action("ui_text_completion_query", true)) {
 		request_code_completion(true);
diff --git a/scene/gui/line_edit.cpp b/scene/gui/line_edit.cpp
index b6209ab35f..c230e7f8f9 100644
--- a/scene/gui/line_edit.cpp
+++ b/scene/gui/line_edit.cpp
@@ -1052,9 +1052,9 @@ void LineEdit::gui_input(const Ref<InputEvent> &p_event) {
 	_reset_caret_blink_timer();

 	// Allow unicode handling if:
 	// * No Modifiers are pressed (except shift)
-	bool allow_unicode_handling = !(k->is_ctrl_pressed() || k->is_alt_pressed() || k->is_meta_pressed());
+	bool allow_unicode_handling = !(k->is_ctrl_pressed() || k->is_alt_pressed() || k->is_meta_pressed() || (k->get_keycode() >= Key::KP_MULTIPLY && k->get_keycode() <= Key::KP_9));

 	if (allow_unicode_handling && editable && k->get_unicode() >= 32) {
 		// Handle Unicode if no modifiers are active.
 		selection_delete();
diff --git a/scene/gui/text_edit.cpp b/scene/gui/text_edit.cpp
index a8c11414c0..c8aaad31f1 100644
--- a/scene/gui/text_edit.cpp
+++ b/scene/gui/text_edit.cpp
@@ -2621,9 +2621,9 @@ void TextEdit::gui_input(const Ref<InputEvent> &p_gui_input) {
 		_reset_caret_blink_timer();

 		// Allow unicode handling if:
 		// * No modifiers are pressed (except Shift and CapsLock)
-		bool allow_unicode_handling = !(k->is_ctrl_pressed() || k->is_alt_pressed() || k->is_meta_pressed());
+		bool allow_unicode_handling = !(k->is_ctrl_pressed() || k->is_alt_pressed() || k->is_meta_pressed() || (k->get_keycode() >= Key::KP_MULTIPLY && k->get_keycode() <= Key::KP_9));

 		// Check and handle all built-in shortcuts.

 		// NEWLINES.
```

</details>

Have not tested it, but should make shortcuts work, and still allow keypad input when shortcuts aren't in use.
